/* PHEBS ($6B32) - ---DROP THRU -- DECREASE SCREEN FREEZE
 * Condition codes in: C; out: NZVC.
 */
void phebs(void)
{
    CK(0x6B32);
    CYC(8);
    JSR(vewbs);                                      /* L6B32  VIEW BASE TRENCH */
    A = M8(S_GAS);                                   /* L6B35 */
    CYC(9 + (((A & 0x80)) ? 1 : 0));
    if ((A & 0x80)) { phib0d(); return; }            /* L6B37  J EXIT WHEN PLAYER DIES */
    CYC(8);
    JSR(mvgun);                                      /* L6B3B */
    CYC(8);
    JSR(mvptgn);                                     /* L6B3E  PLAYERS PROTON TORP GUN */
    CYC(8);
    JSR(dobase);                                     /* L6B41  FIRES BASES SHOTS */
    CYC(8);
    JSR(do1qglw);                                    /* L6B44  QUICKER GLOW IN TRENCH SEQUENCES */
    CYC(8);
    JSR(do1gas);                                     /* L6B47 */
    /* TWIRL THE SHIP THRU THE WORMHOLE */
    CYC(8);
    JSR(vgtosite);                                   /* L6B4A  PULL IN SITE COORDS FROM IRQ RHEOSTATS */
    CYC(8);
    JSR(s1twbs);                                     /* L6B4D */
    A = MS_S1BC;                                     /* L6B50 */
    CYC(10);
    JSR(is1uv);                                      /* L6B52 */
    CYC(8);
    JSR(s1mvbs);                                     /* L6B55  BASE TRENCH CONTROLS MOTION */
    A = M8(FRAME+1);                                 /* L6B58 */
    A &= 0x0F;                                       /* L6B5A */
    CYC(9);
    if (A == 0) {                                    /* L6B5C  IFEQ  ?PSUEDO SECOND PASSED? */
        A = M8(PH_TIM);                              /* L6B5E */
        cmp8(A, 0x02);                               /* L6B61 */
        CYC(10);
        if (CCZ) {                                   /* L6B63  IFEQ  ?FINISHED WITH VOICE OR CURSING R2? */
            CYC(8);
            JSR(pmrrp);                              /* L6B65  THEN DO REBEL REPEAT THEME */
        }
        A = M8(BS_WAV);                              /* L6B68 */
        A = lsr8(A);                                 /* L6B6B */
        CYC(10);
        if (!CCC) {                                  /* L6B6C  IFCC  BEGIN WITH WAVE 0 SAYING . . . */
            A = M8(PH_TIM);                          /* L6B6E */
            cmp8(A, 0x10);                           /* L6B71 */
            CYC(10);
            if (CCZ) {                               /* L6B73  IFEQ   */
                CYC(8);
                JSR(spktru);                         /* L6B75  LUKE, TRUST ME */
                CYC(3);
            } else {                                 /* L6B78  ELSE   */
                cmp8(A, 0x18);                       /* L6B7A */
                CYC(5);
                if (CCZ) {                           /* L6B7C  IFEQ   */
                    CYC(8);
                    JSR(spkyau);                     /* L6B7E  YAHOO, YOURE ALL CLEAR KID */
                }
            }
            CYC(3);
        } else {                                     /* L6B81  ELSE  ELSE ALTERNATE WAVE */
            A = M8(PH_TIM);                          /* L6B83  OCCURS A BIT SOONER */
            cmp8(A, 0x10);                           /* L6B86 */
            CYC(10);
            if (CCZ) {                               /* L6B88  IFEQ   */
                CYC(8);
                JSR(spklet);                         /* L6B8A  LET GO LUKE */
                CYC(3);
            } else {                                 /* L6B8D  ELSE   */
                cmp8(A, 0x16);                       /* L6B8F */
                CYC(5);
                if (CCZ) {                           /* L6B91  IFEQ   */
                    CYC(8);
                    JSR(spkstr);                     /* L6B93  THE FORCE IS STRONG WITH THIS ONE */
                }
            }
        }
        M8(PH_TIM) = (uint8_t)(M8(PH_TIM) + 1);      /* L6B96 */
        CYC(7);
    }
    A = M8(BS_EFL);                                  /* L6B99 */
    nz8(A);
    CYC(7);
    if (!CCZ) {                                      /* L6B9B  IFNE  ?STARTING TO VIEW END OF TRENCH? */
        D = rd16(BS_ELC);                            /* L6B9D */
        D = (uint16_t)(D - rd16(MS_TX+M_S1));        /* L6B9F */
        D = sub16(D, 0x0800);                        /* L6BA2 */
        CYC(19);
        if ((CCC | CCZ)) {                           /* L6BA5  IFLS  ?ABOUT TO BASH OUR NOSE IN THE END WALL? */
            A = M8(PT_LIV);                          /* L6BA7  DID WE KILL IT?? */
            CYC(8);
            if (A == 0) {                            /* L6BAA  IFEQ  NO, TOO BAD--NO EXPLOSION */
                A = 0x01;                            /* L6BAC */
                M8(Q_BSH) = A;                       /* L6BAE  FLAG FOR BASHED OUR NOSE */
                CYC(15);
                JSR(audcr);                          /* L6BB1  CRASHED */
                CYC(8);
                JSR(bg1glw);                         /* L6BB4  BASHED OUR NOSE -- LIMITS REPEATS */
                A = M8(S_GAS);                       /* L6BB7  ?WILL THIS KILL PLAYER? */
                nz8(A);
                CYC(9 + (((CCZ | (CCN ^ CCV))) ? 1 : 0));
                if ((CCZ | (CCN ^ CCV))) { phib0d(); return; } /* L6BB9  THEN EXIT */
                /* ELSE */
                A = PHS_B0B;                         /* L6BBD  TRY TRENCH AGAIN UNTIL SUCCESSFUL */
                M8(PHASE) = A;                       /* L6BBF */
                CYC(14);
                JSR(spkr2n);                         /* L6BC1  R2 SWEARS AT PLAYER FOR MISSING EXHAUST PORT */
                CYC(3);
            } else {                                 /* L6BC4  ELSE  YES, LET'S WATCH IT EXPLODE! */
                A = PHS_DX1;                         /* L6BC6 */
                M8(PHASE) = A;                       /* L6BC8 */
                A = M8(GM_WAV);                      /* L6BCA */
                cmp8(A, 0x03);                       /* L6BCD */
                CYC(16);
                if (!(CCN ^ CCV)) {                  /* L6BCF  IFGE  ?WAVE 4 OR HIGHER? */
                    A = and8(A, 0x01);               /* L6BD1 */
                    CYC(5);
                    if (!CCZ) {                      /* L6BD3  IFNE  ?ANDIF AN EVEN(ODD-1) WAVE? */
                        CYC(8);
                        JSR(spkgre);                 /* L6BD5  GREAT SHOT KID, THAT WAS 1 IN A MILLION */
                        CYC(3);
                        goto l_phebs_80;             /* L6BD8 */
                    }
                }
            }
        }
    }
l_phebs_80:;
    CK(0x6BDA);
    CYC(5);
    RTS;                                             /* L6BDA */
}

