/* STWSP1 ($6DD2) - ROLL IF HIT
 * Condition codes in: C.
 */
void stwsp1(void)
{
    CK(0x6DD2);
    A = M8(S_ROL);                                   /* L6DD2 */
    nz8(A);
    CYC(7);
    if (!CCZ) {                                      /* L6DD4  IFNE  ?ANY ROLLING TO DO? */
        CYC(3);
        if (!(CCZ | (CCN ^ CCV))) {                  /* L6DD6  IFGT  ?POSITIVE? */
            M8(S_ROL) = (uint8_t)(M8(S_ROL) - 1);    /* L6DD8 */
            D = 0x04FF;                              /* L6DDA */
            CYC(12);
        } else {                                     /* L6DDD  ELSE  ELSE NEGATIVE */
            M8(S_ROL) = (uint8_t)(M8(S_ROL) + 1);    /* L6DDF */
            D = 0xFB01;                              /* L6DE1 */
            CYC(9);
        }
        wr16(M_SIN, D);                              /* L6DE4 */
        D = 0x3FCE;                                  /* L6DE7  4.48 DEGREES */
        wr16(M_COS, D);                              /* L6DEA */
        CYC(23);
        JSR(s1rl);                                   /* L6DED */
    }
    CYC(8);
    JSR(aim);                                        /* L6DF0  AIM AT ALIEN OR DETH STAR */
    CYC(8);
    JSR(s1rhpt);                                     /* L6DF3 */
    CYC(8);
    JSR(s1rhyw);                                     /* L6DF6 */
    CYC(5);
    RTS;                                             /* L6DF9 */
}

