/* S1TWGD ($6E22)
 */
void s1twgd(void)
{
    CK(0x6E22);
    A = M8(S_ROL);                                   /* L6E22 */
    nz8(A);
    CYC(7);
    if (!CCZ) {                                      /* L6E24  IFNE  ?TIME TO ROLL PLAYER? */
        CYC(3);
        if (!(CCZ | (CCN ^ CCV))) {                  /* L6E26  IFGT   */
            A = (uint8_t)(A - 1);                    /* L6E28  GO TOWARDS ZERO */
            CYC(5);
        } else {                                     /* L6E29  ELSE   */
            A = (uint8_t)(A + 1);                    /* L6E2B  GO TOWARDS ZERO */
            CYC(2);
        }
        M8(S_ROL) = A;                               /* L6E2C */
        CYC(4);
    }
    A = M8(S_ROL);                                   /* L6E2E */
    CYC(7);
    if ((A & 0x80)) {                                /* L6E30  IFMI   */
        A = (uint8_t)(0 - A);                        /* L6E32  ABS FOR MULTIPLIER */
        CYC(2);
    }
    B = 0x20;                                        /* L6E33  15 PER DEGREE PER COUNT */
    D = (uint16_t)(A * B);                           /* L6E35 */
    CYC(22);
    if ((M8(S_ROL) & 0x80)) {                        /* L6E38  IFMI   */
        A = (uint8_t)~A;                             /* L6E3A  NEGD  RESTORE SIGN */
        B = neg8(B);                                 /* L6E3B  NEGD  RESTORE SIGN */
        A = sbc8(A, 0xFF);                           /* L6E3C  NEGD  RESTORE SIGN */
        CYC(6);
    }
    wr16(GD_ROL, D);                                 /* L6E3E  AMOUNT OF OFFSET TO ROLL */
    A = M8(SI_RSX);                                  /* L6E40  NOW ROLL CUZ OF PLAYER AIM */
    CYC(12);
    if ((A & 0x80)) {                                /* L6E42  IFMI   */
        A = (uint8_t)~A;                             /* L6E44 */
        CYC(2);
    }
    B = 0x02;                                        /* L6E45  MAX COUNT OF 5*128=45 DEGREES(78 PER 5 DEGREES) */
    /* USE 4 MAX SO DOUBLE SHIFT GET 8 BITS */
    D = (uint16_t)(A * B);                           /* L6E47 */
    CYC(22);
    if ((M8(SI_RSX) & 0x80)) {                       /* L6E4A  IFMI   */
        A = (uint8_t)~A;                             /* L6E4C  NEGD  RESTORE SIGN */
        B = neg8(B);                                 /* L6E4D  NEGD  RESTORE SIGN */
        A = sbc8(A, 0xFF);                           /* L6E4E  NEGD  RESTORE SIGN */
        CYC(6);
    }
    D = (uint16_t)(D + rd16(GD_ROL));                /* L6E50 */
    CYC(15);
    if (M8(S_ROL) == 0) {                            /* L6E54  IFEQ  ?NO FANCY COLLISION ROLL?THEN GO SLOW */
        D = sub16(D, rd16(GD_ACT));                  /* L6E56  COMPARE WITH ACTUAL ROLL AMOUNT */
        CYC(9);
        if (!(CCZ | (CCN ^ CCV))) {                  /* L6E58  IFGT  ?ROLL PLUS? */
            /* CMPD 0x0010 */                        /* L6E5A  LIMIT PLUS ROLL */
            CYC(8);
            if ((int16_t)D > (int16_t)0x0010) {      /* L6E5E  IFGT   */
                D = 0x0010;                          /* L6E60  127.(BYTE MAX)-77.(RESIDU MOST)=50.(MAX INCREASE ALLOWED) */
                CYC(3);
            }
            CYC(3);
        } else {                                     /* L6E63  ELSE   */
            /* CMPD 0xFFF0 */                        /* L6E65  LIMIT MINUS ROLL */
            CYC(8);
            if ((int16_t)D < (int16_t)0xFFF0) {      /* L6E69  IFLT   */
                D = 0xFFF0;                          /* L6E6B */
                CYC(3);
            }
        }
        CYC(3);
        l6e88(); return;                             /* L6E6E  ELSE  ELSE IS FANCY ROLL */
    }
    untwgd();                                        /* falls into UNTWGD */
}

/* UNTWGD ($6E70) - REMEMBER TO UNTWIST ANY GROUND MOVEMENT
 * Condition codes out: NZVC.
 */
void untwgd(void)
{
    CK(0x6E70);
    D = sub16(D, rd16(GD_ACT));                      /* L6E70  COMPARE WITH ACTUAL ROLL AMOUNT */
    CYC(9);
    if (!(CCZ | (CCN ^ CCV))) {                      /* L6E72  IFGT  ?ROLL PLUS? */
        /* CMPD 0x0032 */                            /* L6E74  LIMIT PLUS ROLL */
        CYC(8);
        if ((int16_t)D > (int16_t)0x0032) {          /* L6E78  IFGT   */
            D = 0x0032;                              /* L6E7A  127.(BYTE MAX)-77.(RESIDU MOST)=50.(MAX INCREASE ALLOWED) */
            CYC(3);
        }
        CYC(3);
    } else {                                         /* L6E7D  ELSE   */
        /* CMPD 0xFFCE */                            /* L6E7F  LIMIT MINUS ROLL */
        CYC(8);
        if ((int16_t)D < (int16_t)0xFFCE) {          /* L6E83  IFLT   */
            D = 0xFFCE;                              /* L6E85 */
            CYC(3);
        }
    }
    l6e88();                                         /* falls into L6E88 */
}

/* L6E88 ($6E88)
 * Condition codes out: NZVC.
 */
void l6e88(void)
{
    CK(0x6E88);
    A = B;                                           /* L6E88  SAVE A COPY */
    A = (uint8_t)(A + M8(RHS_RSD+RHEOR));            /* L6E8A  TICS TO ROLL */
    M8(RHS_RSD+RHEOR) = A;                           /* L6E8D */
    A = (B & 0x80) ? 0xFF : 0x00;                    /* L6E90  GET BACK TO 16 BITS */
    D = (uint16_t)(D + rd16(GD_ACT));                /* L6E91  AND KEEP TRACK OF ACTUAL ROLL */
    wr16(GD_ACT, D);                                 /* L6E93 */
    X = RHEOR;                                       /* L6E95 */
    CYC(40);
    JSR(rhrsdu);                                     /* L6E98 */
    CYC(3);
    if (!CCZ) {                                      /* L6E9B  IFNE  ?HAVE SOME ROLLING TO DO? */
        CYC(8);
        JSR(s1rl);                                   /* L6E9D */
    }
    CYC(5);
    RTS;                                             /* L6EA0 */
}

