/* AIM ($6EA2) - AIM AT ALIEN OR DETH STAR
 */
void aim(void)
{
    CK(0x6EA2);
    X = rd16(AM_PTR);                                /* L6EA2 */
    CYC(9);
    if (X == 0) {                                    /* L6EA5  IFEQ  CYCLE THRU STARTING AT CURRENT POSITION */
        X = ALIEN;                                   /* L6EA7 */
        CYC(3);
    }
    do {
        CK(0x6EAA);
        A = rd8((uint16_t)(X + AS_TYP));             /* L6EAA */
        CYC(10);
        if (A == 0x01) {                             /* L6EAE  IFEQ  ?FOUND OUR FIRST LIVE ALIEN? */
            A = rd8((uint16_t)(X + AS_GLW));         /* L6EB0 */
            CYC(8);
            if (A == 0) {                            /* L6EB2  IFEQ  ?AND NOT GLOWING FROM A HIT? */
                wr16(S2_PRM, X);                     /* L6EB4  SAVE ALIEN POINTER */
                CYC(9);
                aima(); return;                      /* L6EB6 */
            }
        }
        A = M8(Q_SHK);                               /* L6EB9 */
        nz8(A);
        CYC(8);
        if (!(CCZ | (CCN ^ CCV))) {                  /* L6EBC  IFGT  ?STILL WAITING FOR GOOD OPPONENT? */
            A = 0x09;                                /* L6EBE */
            M8(Q_SHK) = A;                           /* L6EC0  # OF SHOTS BEFORE 'I CANT SHAKE HIM' */
            CYC(7);
        }
        X = (uint16_t)(X + AS_IZE);                  /* L6EC3  GET NEW ALIEN TO AIM AT */
        CYC(12);
    } while (X < ALIENZ);                            /* L6EC9  HSEND  LOOP TILL DONE */
    aimdth();                                        /* falls into AIMDTH */
}

/* AIMDTH ($6ECB)
 */
void aimdth(void)
{
    CK(0x6ECB);
    D = 0x0000;                                      /* L6ECB */
    wr16(AM_PTR, D);                                 /* L6ECE  NO CURRENT POINTER TO ALIEN BEING TRACKED */
    A = M8(0x5080);                                  /* L6ED1 */
    CYC(17);
    if (!(A & 0x80)) {                               /* L6ED4  IFPL  ?DETH STAR IN FRONT? */
        B = M8(0x5084);                              /* L6ED6  THEN SLEW NORMALLY(USE HITE OF DETHSTAR) */
        CYC(8);
    } else {                                         /* L6ED9  ELSE  ELSE DETH STAR IN BACK */
        B = 0x7F;                                    /* L6EDB  STRAIGHT IN BACK GIVES LARGE VALUE */
        B = (uint8_t)(B - M8(0x5084));               /* L6EDD */
        CYC(7);
    }
    M8(RHS_RAT+RHEOP) = B;                           /* L6EE0 */
    A = M8(0x5080);                                  /* L6EE3 */
    CYC(13);
    if (!(A & 0x80)) {                               /* L6EE6  IFPL  ?DETH STAR IN FRONT? */
        B = M8(0x5082);                              /* L6EE8  THEN SLEW NORMALLY(USE WIDTH OF DETHSTAR) */
        CYC(8);
    } else {                                         /* L6EEB  ELSE  ELSE DETH STAR IN BACK */
        B = 0x7F;                                    /* L6EED  STRAIGHT IN BACK GIVES LARGE VALUE */
        B = (uint8_t)(B - M8(0x5082));               /* L6EEF */
        CYC(7);
    }
    B = (uint8_t)~B;                                 /* L6EF2 */
    M8(RHS_RAT+RHEOY) = B;                           /* L6EF3 */
    CYC(12);
    RTS;                                             /* L6EF6 */
}

/* AIMA ($6EF7)
 */
void aima(void)
{
    CK(0x6EF7);
    A = MS_S1BC;                                     /* L6EF7 */
    CYC(10);
    JSR(is1uv);                                      /* L6EF9  DOWNLOAD LATEST UNIT VECTOR */
    CYC(8);
    JSR(residu);                                     /* L6EFC  AND HANDLE RESIDU */
    X = rd16(S2_PRM);                                /* L6EFF  GET THE ALIEN TO AIM AT */
    wr16(AM_PTR, X);                                 /* L6F01  SAVE OUR CURRENT ALIEN */
    A = 0;                                           /* L6F04 */
    B = rd8((uint16_t)(X + AS_BIC));                 /* L6F05 */
    B = add8(B, 0x03);                               /* L6F07 */
    CYC(20);
    hw_wr16(M_BIC, D);                               /* L6F09 */
    A = MS_PSB2;                                     /* L6F0C */
    CYC(16);
    JSR(mgowt);                                      /* L6F0E  GET ALIENS LATEST LOC VIA PLAYER */
    A = M8(M_XP);                                    /* L6F11 */
    nz8(A);
    CYC(8);
    if (!(CCZ | (CCN ^ CCV))) {                      /* L6F14  IFGT  ?ALIEN IN FRONT? */
        D = rd16(M_YP);                              /* L6F16  THEN SCALE USING X */
        CYC(6);
        do {
            CK(0x6F19);
            M8(M_XP+1) = asl8(M8(M_XP+1));           /* L6F19 */
            M8(M_XP) = rol8(M8(M_XP));               /* L6F1C */
            CYC(17);
            if (CCV) goto l_aima_26;                 /* L6F1F  B WHEN X OVERFLOWS */
            B = asl8(B);                             /* L6F21  LSLD  NOW DO Y */
            A = rol8(A);                             /* L6F22  LSLD  NOW DO Y */
            CYC(7);
            if (CCV) {                               /* L6F23  IFVS  ?Y AT MAX SCALE? */
                A = ror8(A);                         /* L6F25  RORD  THEN RESTORE SIGN */
                B = ror8(B);                         /* L6F26  RORD  THEN RESTORE SIGN */
                CYC(7);
                goto l_aima_26;                      /* L6F27  J AND SKIP OUT */
            }
            M8(M_ZP+1) = asl8(M8(M_ZP+1));           /* L6F29 */
            M8(M_ZP) = rol8(M8(M_ZP));               /* L6F2C */
            CYC(17);
        } while (!CCV);                              /* L6F2F  VSEND   */
        M8(M_ZP) = ror8(M8(M_ZP));                   /* L6F31  RESTORE CORRECT SIGN */
        M8(M_ZP+1) = ror8(M8(M_ZP+1));               /* L6F34 */
        CYC(17);
    } else {                                         /* L6F37  ELSE  ELSE ALIEN IS BEHIND -- USE LARGEST SCALE */
        D = rd16(M_YP);                              /* L6F39  PREPARE DREG FOR SPEED */
        B |= 0x01;                                   /* L6F3C  FORCE END TO LOOP */
        CYC(8);
        do {
            CK(0x6F3E);
            B = asl8(B);                             /* L6F3E  LSLD  NOW DO Y */
            A = rol8(A);                             /* L6F3F  LSLD  NOW DO Y */
            CYC(7);
            if (CCV) {                               /* L6F40  IFVS  ?Y AT MAX SCALE? */
                A = ror8(A);                         /* L6F42  RORD  THEN RESTORE SIGN */
                B = ror8(B);                         /* L6F43  RORD  THEN RESTORE SIGN */
                CYC(7);
                goto l_aima_26;                      /* L6F44  J AND SKIP OUT */
            }
            M8(M_ZP+1) = asl8(M8(M_ZP+1));           /* L6F46 */
            M8(M_ZP) = rol8(M8(M_ZP));               /* L6F49 */
            CYC(17);
        } while (!CCV);                              /* L6F4C  VSEND   */
        M8(M_ZP) = ror8(M8(M_ZP));                   /* L6F4E  RESTORE CORRECT SIGN */
        M8(M_ZP+1) = ror8(M8(M_ZP+1));               /* L6F51 */
        CYC(14);
    }
l_aima_26:;
    CK(0x6F54);
    A = (uint8_t)~A;                                 /* L6F54  DREG := SHIFTED Y */
    M8(RHS_RAT+RHEOY) = A;                           /* L6F55  LEFT/RIGHT YAW */
    B = M8(M_ZP);                                    /* L6F58 */
    M8(RHS_RAT+RHEOP) = B;                           /* L6F5B  UP/DOWN PITCH */
    CYC(22);
    RTS;                                             /* L6F5E */
}

