/* VWMES ($761D) - SCORE AND STUFF
 */
void vwmes(void)
{
    CK(0x761D);
    D = VJTITL;                                      /* L761D */
    wr16(Y, D);                                      /* L7620 */
    Y = (uint16_t)(Y + 2);
    D = ((VGCGRN*0x100)+VGCOPC);                     /* L7622  BRITE */
    wr16(Y, D);                                      /* L7625 */
    Y = (uint16_t)(Y + 2);
    D = (VGRW3&0x1FFF);                              /* L7627  HI UP */
    wr16(Y, D);                                      /* L762A */
    Y = (uint16_t)(Y + 2);
    D = ((VGLIML+(0*VGS_CW))&0x1FFF);                /* L762C  LEFT */
    wr16(Y, D);                                      /* L762F */
    Y = (uint16_t)(Y + 2);
    A = 0x06;                                        /* L7631  ZERO SUPPRESS TOP 6 DIGITS */
    M8(BT_SUP) = A;                                  /* L7633 */
    X = S_SC87;                                      /* L7635 */
    CYC(61);
    JSR(vw8dig);                                     /* L7638  COMPLETE WITH COMMAS */
    D = VGCNTR;                                      /* L763B */
    wr16(Y, D);                                      /* L763E */
    Y = (uint16_t)(Y + 2);
    /* SHOW LAST SCORE ADDED IN */
    B = M8(SC_ADT);                                  /* L7640  TIMER */
    CYC(19);
    if (B != 0) {                                    /* L7643  IFNE  STILL VISIBLE, SHOW IT */
        B = (uint8_t)(B - 0x08);                     /* L7645 */
        CYC(7);
        if (B < 0x20) {                              /* L7649  IFLO   */
            B = 0x00;                                /* L764B */
            CYC(2);
        }
        M8(SC_ADT) = B;                              /* L764D  USE TIMER FOR BRIGHTNESS */
        B = (uint8_t)(B >> 1);                       /* L7650 */
        A = 0x66;                                    /* L7651 */
        wr16(Y, D);                                  /* L7653 */
        Y = (uint16_t)(Y + 2);
        D = (VGRW5&0x1FFF);                          /* L7655  Y POS */
        wr16(Y, D);                                  /* L7658 */
        Y = (uint16_t)(Y + 2);
        D = ((VGLIML+(2*VGS_CW))&0x1FFF);            /* L765A  X POS */
        wr16(Y, D);                                  /* L765D */
        Y = (uint16_t)(Y + 2);
        A = 0x05;                                    /* L765F  SUPRESS 5 LEADING ZEROES */
        M8(BT_SUP) = A;                              /* L7661 */
        X = (SC_ADD-1);                              /* L7663  X-->8 DIGIT FIELD, EVEN THO ONLY LO 6 SHOW */
        CYC(56);
        JSR(vw6dig);                                 /* L7666  6 DIGITS WITH COMMAS */
        D = VGCNTR;                                  /* L7669 */
        wr16(Y, D);                                  /* L766C */
        Y = (uint16_t)(Y + 2);
        CYC(11);
    }
    /* SHOW WAVE NUMBER */
    D = ((VGCGRN*0x100)+VGCOPC);                     /* L766E  COLOR BRITE */
    wr16(Y, D);                                      /* L7671 */
    Y = (uint16_t)(Y + 2);
    D = (VGRW1&0x1FFF);                              /* L7673  Y UP HI */
    wr16(Y, D);                                      /* L7676 */
    Y = (uint16_t)(Y + 2);
    D = ((VGLIMR-((2+5)*VGS_CW))&0x1FFF);            /* L7678  X RIGHT */
    wr16(Y, D);                                      /* L767B */
    Y = (uint16_t)(Y + 2);
    A = 0x01;                                        /* L767D  ZERO SUPPRES TOP 1 DIGIT */
    M8(BT_SUP) = A;                                  /* L767F */
    A = M8(GM_DWAV);                                 /* L7681  BCD WAVE NUMBER */
    CYC(52);
    JSR(vwbyte);                                     /* L7684 */
    D = VGCNTR;                                      /* L7687 */
    wr16(Y, D);                                      /* L768A */
    Y = (uint16_t)(Y + 2);
    CYC(16);
    RTS;                                             /* L768C */
}

