/* BINBCD ($7720) - CONVERT POSITIVE BINARY TO BCD
 *   INPUT BINARY IN D, NUMBER OF SHIFTS IN X
 *   OUTPUT IS BCD IN BCD,BCD+1,BCD+2
 */
void binbcd(void)
{
    CK(0x7720);
    wr16(BIN, D);                                    /* L7720 */
    D = 0x0000;                                      /* L7723 */
    wr16(BCD, D);                                    /* L7726 */
    M8(BCD+2) = A;                                   /* L7729 */
    CYC(20);
    do {
        CK(0x772C);
        M8(BIN+1) = asl8(M8(BIN+1));                 /* L772C */
        M8(BIN) = rol8(M8(BIN));                     /* L772F */
        A = M8(BCD+2);                               /* L7732 */
        A = adc8(A, M8(BCD+2));                      /* L7735 */
        daa_a();                                     /* L7738 */
        M8(BCD+2) = A;                               /* L7739 */
        A = M8(BCD+1);                               /* L773C */
        A = adc8(A, M8(BCD+1));                      /* L773F */
        daa_a();                                     /* L7742 */
        M8(BCD+1) = A;                               /* L7743 */
        M8(BCD) = rol8(M8(BCD));                     /* L7746 */
        X = (uint16_t)(X - 1);                       /* L7749 */
        CYC(63);
    } while (X != 0);                                /* L774B  EQEND   */
    CYC(5);
    RTS;                                             /* L774D */
}

/* BCDBIN ($774E) - CONVERT 2 POSITIVE BCD DIGITS TO BINARY
 *   INPUT A, OUTPUT BIN
 */
void bcdbin(void)
{
    CK(0x774E);
    M8(BIN) = A;                                     /* L774E */
    A &= 0xF0;                                       /* L7751  USE FIRST NYBBLE */
    B = 0xA0;                                        /* L7753 */
    D = (uint16_t)(A * B);                           /* L7755  ACC A CONTAINS FIRST DIGIT*10. */
    B = M8(BIN);                                     /* L7756 */
    B &= 0x0F;                                       /* L7759 */
    M8(BIN) = B;                                     /* L775B */
    A = (uint8_t)(A + M8(BIN));                      /* L775E */
    M8(BIN) = A;                                     /* L7761 */
    CYC(47);
    RTS;                                             /* L7764 */
}

